SELECT * FROM (SELECT CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, country, COUNT(*) AS total_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values FROM suppliers WHERE supplier_name NOT LIKE '%Tok%' GROUP BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END, country) AS s WHERE total_count > 9 ORDER BY total_count DESC
